mapper.select:
select bcipm.id,bcipm.create_time,bcipm.m_cus_batch_number_list as m_cus_batch_number
     ,bcipm.m_model,bcipm.m_model_version,bcipm.m_num_min,bcipm.m_num_max
     ,bcipm.m_score_min,bcipm.m_score_max,bcipm.m_realy_num,bcipm.m_status
from b_customer_info_push_main bcipm

    left join b_customer_info_push_batch bcipb on bcipm .id = bcipb .m_id and bcipb .is_del =1
    left join stra_his_file shf on bcipb.m_file_id = shf.id

where bcipm .m_api_code = #{mApiCode}

      and bcipm .m_status = #{mStatus}


        and bcipm .create_time >=#{pushBeginTime} 


      and bcipm .create_time <=#{pushEndTime} 


      and shf .show_title =#{cusBatchNumber}

    and bcipm .m_status != -1
    and bcipm .is_del =1
    order by bcipm.id desc

select id, m_api_code as api_code, m_cus_batch_number_list as mCusBatchNumberList, m_rule_condition_show as mRuleConditionShow, m_rule_condition as mRuleCondition, m_score_condition as mScoreCondition, m_realy_num as mRealyNum, m_plan_num as mPlanNum, m_percentage as mPercentage, DATE_FORMAT(create_time,'%Y-%m-%d %H:%i:%s') as createTime, m_status as mStatus, batch_name as batchName, push_target as pushTarget, extend, upload_report_ids as uploadReportIds from b_customer_info_push_main where is_del=1 and m_status !=-1
and push_target in
#{item}
and m_api_code = #{dto.mApiCode}
and create_time >=#{dto.pushBeginTime}
and create_time <=#{dto.pushEndTime}
and id = #{dto.pushInfoId}
and m_status in
#{item}
order by create_time desc,update_time desc,id desc
